#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// OASIS MQTT 3.1.1 §3.12 PINGREQ: type 12, remaining length 0.
    fn vector() -> Vec<u8> {
        vec![0xc0, 0x00]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::Mqtt);
        let l = p.find_layer(ProtoId::Mqtt).unwrap();
        assert_eq!(p.get(l, "type").unwrap(), FieldValue::Uint(12));
        assert_eq!(p.get(l, "DUP").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "QOS").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "RETAIN").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::Mqtt);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::Mqtt);
        let l = p.find_layer(ProtoId::Mqtt).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::Mqtt, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
